mapper.delete:
DELETE FROM stk_holdertrade WHERE

    (ts_code = #{i.tsCode} AND ann_date = #{i.annDate}
     AND holder_name = #{i.holderName} AND in_de = #{i.inDe}
     AND begin_date = #{i.beginDate} AND close_date = #{i.closeDate})

mapper.select:
SELECT * FROM stk_holdertrade
WHERE ts_code = #{tsCode}

    AND ann_date >= #{startDate}


    AND ann_date <= #{endDate}

ORDER BY ann_date DESC, close_date DESC, begin_date DESC, id DESC
